using System.Reflection;namespace KUKULCAN.SharedKernel.UnitTests.Helpers.Internal;/// <summary>/// Automatic cache cleanup operations./// </summary>internal static partial class ReflectionCache{    /// <summary>    /// Performs the default cache cleanup.    /// </summary>    public static int Cleanup() => CleanupExpired();    /// <summary>    /// Removes every expired cache entry.    /// </summary>    public static int CleanupExpired() => Purge();    /// <summary>    /// Removes every cache entry created before the specified instant.    /// </summary>    public static int CleanupCreatedBefore(DateTimeOffset instant) => RemoveCreatedBefore(instant);    /// <summary>    /// Removes every cache entry created after the specified instant.    /// </summary>    public static int CleanupCreatedAfter(DateTimeOffset instant) => RemoveCreatedAfter(instant);    /// <summary>    /// Removes every cache entry accessed before the specified instant.    /// </summary>    public static int CleanupAccessedBefore(DateTimeOffset instant) => RemoveAccessedBefore(instant);    /// <summary>    /// Removes every cache entry accessed after the specified instant.    /// </summary>    public static int CleanupAccessedAfter(DateTimeOffset instant) => RemoveAccessedAfter(instant);    /// <summary>    /// Removes every cache entry that has never been accessed.    /// </summary>    public static int CleanupNeverAccessed() => RemoveIf(static entry => entry.AccessCount == 0);    /// <summary>    /// Removes every cache entry accessed fewer than the specified number of times.    /// </summary>    public static int CleanupAccessedLessThan(long accessCount)    {        ArgumentOutOfRangeException.ThrowIfNegative(accessCount);        return RemoveIf(entry => entry.AccessCount < accessCount);    }    /// <summary>    /// Removes every cache entry accessed more than the specified number of times.    /// </summary>    public static int CleanupAccessedGreaterThan(long accessCount)    {        ArgumentOutOfRangeException.ThrowIfNegative(accessCount);        return RemoveIf(entry => entry.AccessCount > accessCount);    }    /// <summary>    /// Removes every cache entry older than the specified age.    /// </summary>    public static int CleanupOlderThan(TimeSpan age)    {        ThrowIfNegative(age, nameof(age));        return CleanupCreatedBefore(            DateTimeOffset.UtcNow - age);    }    /// <summary>    /// Removes every cache entry inactive for the specified period.    /// </summary>    public static int CleanupInactiveFor(TimeSpan inactivity)    {        ThrowIfNegative(inactivity, nameof(inactivity));        return CleanupAccessedBefore(            DateTimeOffset.UtcNow - inactivity);    }    /// <summary>    /// Removes every cache entry belonging to the specified category.    /// </summary>    public static int CleanupCategory(string category)    {        ArgumentException.ThrowIfNullOrWhiteSpace(category);        return RemoveByCategory(category);    }    /// <summary>    /// Removes every cache entry associated with the specified owner type.    /// </summary>    public static int CleanupType(Type ownerType)    {        ArgumentNullException.ThrowIfNull(ownerType);        return RemoveByType(ownerType);    }    /// <summary>    /// Removes every cache entry associated with the specified assembly.    /// </summary>    public static int CleanupAssembly(Assembly assembly)    {        ArgumentNullException.ThrowIfNull(assembly);        return RemoveByAssembly(assembly);    }    /// <summary>    /// Removes every cache entry associated with the specified module.    /// </summary>    public static int CleanupModule(Module module)    {        ArgumentNullException.ThrowIfNull(module);        return RemoveByModule(module);    }    /// <summary>    /// Removes every cache entry belonging to the specified namespace.    /// </summary>    public static int CleanupNamespace(string @namespace)    {        ArgumentException.ThrowIfNullOrWhiteSpace(@namespace);        return RemoveByNamespace(@namespace);    }    /// <summary>    /// Removes every cache entry associated with the specified generic type definition.    /// </summary>    public static int CleanupGenericType(Type genericTypeDefinition)    {        ArgumentNullException.ThrowIfNull(genericTypeDefinition);        return RemoveByGenericType(genericTypeDefinition);    }    /// <summary>    /// Removes every cache entry whose cached value is assignable to the specified type.    /// </summary>    public static int CleanupValueType(Type valueType)    {        ArgumentNullException.ThrowIfNull(valueType);        return RemoveByValueType(valueType);    }    /// <summary>    /// Removes every cache entry assignable to the specified base type.    /// </summary>    public static int CleanupAssignableTo(Type baseType)    {        ArgumentNullException.ThrowIfNull(baseType);        return RemoveByAssignableType(baseType);    }    /// <summary>    /// Removes every cache entry containing metadata.    /// </summary>    public static int CleanupWithMetadata() => RemoveWithMetadata();    /// <summary>    /// Removes every cache entry without metadata.    /// </summary>    public static int CleanupWithoutMetadata() => RemoveWithoutMetadata();    /// <summary>    /// Removes every cache entry whose cached value is null.    /// </summary>    public static int CleanupNullValues() => RemoveIf(static entry => entry.Value is null);    /// <summary>    /// Removes every cache entry with empty metadata.    /// </summary>    public static int CleanupEmptyMetadata() => RemoveIf(static entry => entry.Metadata.Count == 0);    /// <summary>    /// Removes every cache entry matching the specified entry predicate.    /// </summary>    public static int Cleanup(Func<ReflectionCacheEntry, bool> predicate)    {        ArgumentNullException.ThrowIfNull(predicate);        return RemoveIf(predicate);    }    /// <summary>    /// Removes every cache entry matching the specified key predicate.    /// </summary>    public static int Cleanup(Func<ReflectionCacheKey, bool> predicate)    {        ArgumentNullException.ThrowIfNull(predicate);        return RemoveWhere(predicate);    }    /// <summary>    /// Removes every cache entry matching the specified cache predicate.    /// </summary>    public static int Cleanup(Func<KeyValuePair<ReflectionCacheKey, ReflectionCacheEntry>, bool> predicate)    {        ArgumentNullException.ThrowIfNull(predicate);        return RemoveWhere(predicate);    }    /// <summary>    /// Removes every cache entry.    /// </summary>    public static int CleanupAll() => RemoveAll();    /// <summary>    /// Removes every cache entry and returns the removed entries.    /// </summary>    public static IReadOnlyList<ReflectionCacheEntry> CleanupAllWithResult() => RemoveAllWithResult();    /// <summary>    /// Performs cleanup followed by cache compaction.    /// </summary>    public static int Optimize() => Compact();    /// <summary>    /// Compacts the cache.    /// </summary>    public static int CompactCache() => Compact();    /// <summary>    /// Removes expired entries and compacts the cache.    /// </summary>    public static int Shrink() => Compact();    /// <summary>    /// Determines whether cleanup is required.    /// </summary>    public static bool RequiresCleanup() => HasExpiredEntries();    /// <summary>    /// Determines whether cleanup is required using the specified predicate.    /// </summary>    public static bool RequiresCleanup(Func<ReflectionCacheEntry, bool> predicate)    {        ArgumentNullException.ThrowIfNull(predicate);        return HasInvalidatableEntries(predicate);    }    /// <summary>    /// Counts the entries that would be removed by the specified predicate.    /// </summary>    public static int CountCleanupCandidates(Func<ReflectionCacheEntry, bool> predicate)    {        ArgumentNullException.ThrowIfNull(predicate);        return CountInvalidatableEntries(predicate);    }    /// <summary>    /// Performs cleanup only when required.    /// </summary>    public static int CleanupIfRequired() => RequiresCleanup() ? Cleanup() : 0;    private static void ThrowIfNegative(TimeSpan value, string paramName)    {        if (value < TimeSpan.Zero)        {            throw new ArgumentOutOfRangeException(                paramName,                value,                "The time span cannot be negative.");        }    }}